-- Import URL SDS/TDS nelle schede prodotto dal CSV BulkStrike (match per CAS).
-- Aggiorna solo scheda_sicurezza_url / scheda_tecnica_url; coalesce per non
-- rimuovere valori esistenti. Campi vuoti nel CSV = null (nessun dato inventato).
update products p set
  scheda_sicurezza_url = coalesce(x.s, p.scheda_sicurezza_url),
  scheda_tecnica_url   = coalesce(x.t, p.scheda_tecnica_url)
